[ExportMetadata(enumStr(TAMRebateSourceType), enumLiteralStr(TAMRebateSourceType, METExternalSalesData))]
public final class METTAMRebateJournalTransCustExternalData extends TAMRebateJournalTrans
{    
    METRebateScanSupplierTable rebateScanSupplierTable;
    SalesTable salesTable;

}

