public void inititalizeRebateTransactionFromJournal(TAMRebateTrans _rebateTrans)
{
    super(_rebateTrans);

    /*_rebateTrans.RebateRefAccount = salesTable.InvoiceAccount;
    _rebateTrans.RebateRefId = salesLine.SalesId;
    _rebateTrans.CurrencyCode = salesLine.CurrencyCode;
    _rebateTrans.ItemId = salesLine.ItemId;
    _rebateTrans.RebateRefQty = _rebateTrans.ExcludeRebateManagement ? 0 : (rebateTable.UnitType == PdsUnitType::CWUnit ? salesLine.PdsCWQty : salesLine.SalesQty);
    _rebateTrans.DefaultDimension = salesLine.DefaultDimension;
    _rebateTrans.CashDiscCode = salesTable.CashDisc;
    _rebateTrans.RefUnitId = rebateTable.UnitType == PdsUnitType::CWUnit ? salesLine.pdsCWUnitId() : salesLine.SalesUnit;
    _rebateTrans.InventDimId = salesLine.InventDimId;

    _rebateTrans.RebateRefSoldToAccount = salesTable.InvoiceAccount;*/

    // VNG hope we are not doing catch weight here

    _rebateTrans.RebateRefAccount = rebateScanSupplierTable.CustAccount;
    _rebateTrans.RebateRefId = rebateScanSupplierTable.TransactionNumber;
    _rebateTrans.CurrencyCode = rebateScanSupplierTable.CurrencyCode;
    _rebateTrans.ItemId = rebateScanSupplierTable.ItemId;
    _rebateTrans.RebateRefQty = rebateScanSupplierTable.SalesQty;
    //_rebateTrans.DefaultDimension = salesLine.DefaultDimension;
    _rebateTrans.CashDiscCode = "";
    _rebateTrans.RefUnitId = rebateScanSupplierTable.UnitOfMeasure;
    _rebateTrans.InventDimId = InventDim::findOrCreateBlank().inventDimId;

    _rebateTrans.RebateRefSoldToAccount = rebateScanSupplierTable.CustAccount;

    _rebateTrans.METExternalSalesDataTable = rebateScanSupplierTable.RecId;
}

